INSERT INTO reading_questions (id, group_id, question_order, text, answer) VALUES
('7a32a2f6-9d68-48dc-b783-988cb701c08a', '9c38e9a9-36bf-4124-ba9a-979559f9a722', 36,
 'The debate over artificial consciousness centers on whether a non-biological {{gap_9c38e9a9-36bf-4124-ba9a-979559f9a722_0}} can experience qualia. Functionalists argue against any mystique, claiming consciousness is merely complex processing. Conversely, the "philosophical zombie" argument suggests that highly advanced {{gap_9c38e9a9-36bf-4124-ba9a-979559f9a722_1}} replication does not guarantee subjective experience. If artificial systems do indeed possess phenomenological depth, it raises severe ethical issues, as deleting code could be viewed as causing artificial {{gap_9c38e9a9-36bf-4124-ba9a-979559f9a722_2}}. However, humans must be cautious not to fall prey to anthropomorphic {{gap_9c38e9a9-36bf-4124-ba9a-979559f9a722_3}}, mistakenly equating a machine’s sophisticated semantic {{gap_9c38e9a9-36bf-4124-ba9a-979559f9a722_4}} with genuine feeling. Ultimately, without empirical tests, the truth remains obscured.',
 'substrate'),
('6fb2be39-1586-409a-a4f5-359f678c2f0d', '9c38e9a9-36bf-4124-ba9a-979559f9a722', 37,
 '', 'behavioral'),
('7734c716-e666-4e3f-9d99-d403c0b0307a', '9c38e9a9-36bf-4124-ba9a-979559f9a722', 38,
 '', 'suffering'),
('a6641d0f-cc69-437f-bb69-cd75e097a526', '9c38e9a9-36bf-4124-ba9a-979559f9a722', 39,
 '', 'projection'),
('16dd230d-fe63-488f-9426-d1f496ba826d', '9c38e9a9-36bf-4124-ba9a-979559f9a722', 40,
 '', 'mimicry');

